/* Biến màu / spacing dùng chung — sửa tại đây khi đổi theme */
:root {
  --color-text: #142033;
  --color-muted: #64748b;
  --color-border: #d9e2ef;
  --color-surface: #ffffff;
  --radius-card: 1rem;
  --radius-btn: 0.5rem;
  --space-section: 2rem;

  --color-brand-50: #f0f9ff;
  --color-brand-100: #e0f2fe;
  --color-brand-200: #bae6fd;
  --color-brand-400: #38bdf8;
  --color-brand-500: #0ea5e9;
  --color-brand-600: #0284c7;
  --color-brand-700: #0369a1;
  --color-brand-800: #075985;

  --color-slate-50: #f8fafc;
  --color-slate-100: #f1f5f9;
  --color-slate-200: #e2e8f0;
  --color-slate-300: #cbd5e1;
  --color-slate-400: #94a3b8;
  --color-slate-500: #64748b;
  --color-slate-600: #475569;
  --color-slate-700: #334155;
  --color-slate-800: #1e293b;
  --color-slate-900: #0f172a;

  --color-amber-50: #fffbeb;
  --color-amber-100: #fef3c7;
  --color-amber-300: #fcd34d;
  --color-amber-400: #fbbf24;
  --color-amber-900: #78350f;

  --shadow-soft: 0 8px 30px rgba(15, 23, 42, 0.08);
  --font-sans: 'Be Vietnam Pro', system-ui, sans-serif;

  --bp-sm: 640px;
  --bp-md: 768px;
  --bp-lg: 1024px;
  --bp-xl: 1280px;
}

/* Style nền toàn site */
:root {
  color-scheme: light;
}

body {
  margin: 0;
  background-color: var(--color-slate-50);
  color: var(--color-slate-800);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

/* Layout header, footer, container */
.container-wide {
  width: 100%;
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1rem;
  padding-right: 1rem;
}

@media (min-width: 640px) {
  .container-wide {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }
}

@media (min-width: 1024px) {
  .container-wide {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

.section-block {
  margin-bottom: var(--space-section);
}

.site-header-bar {
  border-bottom: 1px solid var(--color-border);
}

/* Component dùng chung — card, nút, nội dung bài viết */
.card-surface {
  border-radius: var(--radius-card);
  background-color: #fff;
  box-shadow: var(--shadow-soft);
  border: 1px solid var(--color-slate-200);
}

.section-title {
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
  line-height: 1.25;
  font-weight: 700;
  color: var(--color-slate-900);
}

.rich-content h2,
.rich-content h3 {
  margin-top: 1.5rem;
  margin-bottom: 0.75rem;
  font-weight: 700;
  color: var(--color-slate-900);
}

.rich-content h2 {
  font-size: 1.5rem;
}

.rich-content h3 {
  font-size: 1.25rem;
}

.rich-content p {
  margin-bottom: 1rem;
  line-height: 1.75rem;
  color: var(--color-slate-700);
}

.rich-content ul {
  margin-bottom: 1rem;
  padding-left: 1.5rem;
  list-style-type: disc;
  color: var(--color-slate-700);
}

.rich-content ul > li + li {
  margin-top: 0.5rem;
}

.rich-content a {
  color: var(--color-brand-700);
  text-decoration: underline;
}

.rich-content a:hover {
  color: var(--color-brand-800);
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-btn);
  background-color: var(--color-brand-600);
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: #fff;
  transition: background-color 0.15s ease;
}

.btn-primary:hover {
  background-color: var(--color-brand-700);
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-btn);
  border: 1px solid var(--color-slate-300);
  background-color: #fff;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-slate-700);
  transition: border-color 0.15s ease, color 0.15s ease;
}

.btn-outline:hover {
  border-color: var(--color-brand-400);
  color: var(--color-brand-700);
}

/* Utility classes thay thế Tailwind — chỉ giữ class đang dùng trong project */

/* --- Display & flex --- */
.block { display: block; }
.inline-flex { display: inline-flex; }
.flex { display: flex; }
.hidden { display: none; }
.flex-1 { flex: 1 1 0%; }
.flex-wrap { flex-wrap: wrap; }
.shrink-0 { flex-shrink: 0; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }

/* --- Grid --- */
.grid { display: grid; }
.gap-1 { gap: 0.25rem; }
.gap-2 { gap: 0.5rem; }
.gap-3 { gap: 0.75rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.gap-x-4 { column-gap: 1rem; }
.gap-y-2 { row-gap: 0.5rem; }

/* --- Position --- */
.sticky { position: sticky; }
.fixed { position: fixed; }
.relative { position: relative; }
.absolute { position: absolute; }
.inset-0 { inset: 0; }
.top-0 { top: 0; }
.left-0 { left: 0; }
.bottom-0 { bottom: 0; }
.z-30 { z-index: 30; }
.z-40 { z-index: 40; }
.z-50 { z-index: 50; }

/* --- Sizing --- */
.w-full { width: 100%; }
.w-10 { width: 2.5rem; }
.w-24 { width: 6rem; }
.w-80 { width: 20rem; }
.w-1\/3 { width: 33.333333%; }
.w-2\/3 { width: 66.666667%; }
.w-5\/6 { width: 83.333333%; }
.h-full { height: 100%; }
.h-10 { height: 2.5rem; }
.h-16 { height: 4rem; }
.h-44 { height: 11rem; }
.h-48 { height: 12rem; }
.h-auto { height: auto; }
.h-\[360px\] { height: 360px; }
.min-h-screen { min-height: 100vh; }
.min-w-0 { min-width: 0; }
.min-w-10 { min-width: 2.5rem; }
.max-w-xl { max-width: 36rem; }
.max-w-3xl { max-width: 48rem; }
.max-w-\[88\%\] { max-width: 88%; }

/* --- Spacing --- */
.p-1 { padding: 0.25rem; }
.p-4 { padding: 1rem; }
.p-5 { padding: 1.25rem; }
.p-6 { padding: 1.5rem; }
.p-8 { padding: 2rem; }
.px-2 { padding-left: 0.5rem; padding-right: 0.5rem; }
.px-2\.5 { padding-left: 0.625rem; padding-right: 0.625rem; }
.px-3 { padding-left: 0.75rem; padding-right: 0.75rem; }
.px-4 { padding-left: 1rem; padding-right: 1rem; }
.px-5 { padding-left: 1.25rem; padding-right: 1.25rem; }
.py-1 { padding-top: 0.25rem; padding-bottom: 0.25rem; }
.py-1\.5 { padding-top: 0.375rem; padding-bottom: 0.375rem; }
.py-2 { padding-top: 0.5rem; padding-bottom: 0.5rem; }
.py-2\.5 { padding-top: 0.625rem; padding-bottom: 0.625rem; }
.py-3 { padding-top: 0.75rem; padding-bottom: 0.75rem; }
.py-10 { padding-top: 2.5rem; padding-bottom: 2.5rem; }
.pt-4 { padding-top: 1rem; }
.pt-5 { padding-top: 1.25rem; }
.pt-6 { padding-top: 1.5rem; }
.pt-10 { padding-top: 2.5rem; }
.pb-8 { padding-bottom: 2rem; }
.pl-6 { padding-left: 1.5rem; }
.mb-0 { margin-bottom: 0; }
.mb-1 { margin-bottom: 0.25rem; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-3 { margin-bottom: 0.75rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-5 { margin-bottom: 1.25rem; }
.mb-6 { margin-bottom: 1.5rem; }
.mb-8 { margin-bottom: 2rem; }
.mt-1 { margin-top: 0.25rem; }
.mt-2 { margin-top: 0.5rem; }
.mt-3 { margin-top: 0.75rem; }
.mt-4 { margin-top: 1rem; }
.mt-5 { margin-top: 1.25rem; }
.mt-8 { margin-top: 2rem; }
.mt-10 { margin-top: 2.5rem; }
.mx-auto { margin-left: auto; margin-right: auto; }

.space-y-1 > :not([hidden]) ~ :not([hidden]) { margin-top: 0.25rem; }
.space-y-2 > :not([hidden]) ~ :not([hidden]) { margin-top: 0.5rem; }
.space-y-3 > :not([hidden]) ~ :not([hidden]) { margin-top: 0.75rem; }
.space-y-4 > :not([hidden]) ~ :not([hidden]) { margin-top: 1rem; }
.space-y-8 > :not([hidden]) ~ :not([hidden]) { margin-top: 2rem; }

/* --- Typography --- */
.text-xs { font-size: 0.75rem; line-height: 1rem; }
.text-sm { font-size: 0.875rem; line-height: 1.25rem; }
.text-base { font-size: 1rem; line-height: 1.5rem; }
.text-lg { font-size: 1.125rem; line-height: 1.75rem; }
.text-xl { font-size: 1.25rem; line-height: 1.75rem; }
.text-2xl { font-size: 1.5rem; line-height: 2rem; }
.text-3xl { font-size: 1.875rem; line-height: 2.25rem; }
.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }
.font-sans { font-family: var(--font-sans); }
.leading-none { line-height: 1; }
.leading-tight { line-height: 1.25; }
.leading-snug { line-height: 1.375; }
.leading-6 { line-height: 1.5rem; }
.leading-7 { line-height: 1.75rem; }
.uppercase { text-transform: uppercase; }
.tracking-widest { letter-spacing: 0.1em; }
.text-center { text-align: center; }
.text-inherit { color: inherit; }
.truncate { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.antialiased { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

/* --- Colors: text --- */
.text-white { color: #fff; }
.text-slate-100 { color: var(--color-slate-100); }
.text-slate-400 { color: var(--color-slate-400); }
.text-slate-500 { color: var(--color-slate-500); }
.text-slate-600 { color: var(--color-slate-600); }
.text-slate-700 { color: var(--color-slate-700); }
.text-slate-800 { color: var(--color-slate-800); }
.text-slate-900 { color: var(--color-slate-900); }
.text-brand-600 { color: var(--color-brand-600); }
.text-brand-700 { color: var(--color-brand-700); }
.text-amber-900 { color: var(--color-amber-900); }

/* --- Colors: background --- */
.bg-white { background-color: #fff; }
.bg-slate-50 { background-color: var(--color-slate-50); }
.bg-slate-100 { background-color: var(--color-slate-100); }
.bg-slate-200 { background-color: var(--color-slate-200); }
.bg-brand-50 { background-color: var(--color-brand-50); }
.bg-brand-100 { background-color: var(--color-brand-100); }
.bg-brand-600 { background-color: var(--color-brand-600); }
.bg-brand-700 { background-color: var(--color-brand-700); }
.bg-amber-50 { background-color: var(--color-amber-50); }
.bg-amber-100 { background-color: var(--color-amber-100); }
.bg-white\/95 { background-color: rgba(255, 255, 255, 0.95); }
.bg-white\/15 { background-color: rgba(255, 255, 255, 0.15); }
.bg-slate-900\/40 { background-color: rgba(15, 23, 42, 0.4); }
.bg-gradient-to-t {
  background-image: linear-gradient(to top, rgba(15, 23, 42, 0.85), rgba(15, 23, 42, 0.35), transparent);
}

/* --- Borders --- */
.border { border-width: 1px; border-style: solid; }
.border-b { border-bottom-width: 1px; border-bottom-style: solid; }
.border-t { border-top-width: 1px; border-top-style: solid; }
.border-transparent { border-color: transparent; }
.border-slate-100 { border-color: var(--color-slate-100); }
.border-slate-200 { border-color: var(--color-slate-200); }
.border-slate-300 { border-color: var(--color-slate-300); }
.border-brand-400 { border-color: var(--color-brand-400); }
.border-brand-600 { border-color: var(--color-brand-600); }
.border-amber-300 { border-color: var(--color-amber-300); }
.border-amber-400 { border-color: var(--color-amber-400); }

/* --- Border radius --- */
.rounded { border-radius: 0.25rem; }
.rounded-md { border-radius: 0.375rem; }
.rounded-lg { border-radius: var(--radius-btn); }
.rounded-xl { border-radius: 0.75rem; }
.rounded-2xl { border-radius: var(--radius-card); }
.rounded-full { border-radius: 9999px; }

/* --- Effects --- */
.shadow-2xl { box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.25); }
.shadow-soft { box-shadow: var(--shadow-soft); }
.backdrop-blur { backdrop-filter: blur(8px); }
.transition { transition-property: color, background-color, border-color, transform, opacity; transition-duration: 0.15s; transition-timing-function: ease; }
.duration-300 { transition-duration: 0.3s; }
.outline-none { outline: none; }
.object-cover { object-fit: cover; }
.overflow-hidden { overflow: hidden; }
.overflow-x-auto { overflow-x: auto; }
.overflow-y-auto { overflow-y: auto; }
.whitespace-nowrap { white-space: nowrap; }
.list-disc { list-style-type: disc; }
.cursor-default { cursor: default; }

/* --- Line clamp --- */
.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.line-clamp-3 {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* --- Screen reader only --- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* --- Animation --- */
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}
.animate-pulse { animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }

/* --- Group hover --- */
.group:hover .group-hover\:text-brand-700 { color: var(--color-brand-700); }
.group:hover .group-hover\:scale-\[1\.02\] { transform: scale(1.02); }

/* --- Hover --- */
.hover\:bg-brand-50:hover { background-color: var(--color-brand-50); }
.hover\:bg-brand-100:hover { background-color: var(--color-brand-100); }
.hover\:bg-brand-600:hover { background-color: var(--color-brand-600); }
.hover\:bg-brand-700:hover { background-color: var(--color-brand-700); }
.hover\:bg-slate-100:hover { background-color: var(--color-slate-100); }
.hover\:bg-amber-100:hover { background-color: var(--color-amber-100); }
.hover\:text-brand-700:hover { color: var(--color-brand-700); }
.hover\:text-brand-800:hover { color: var(--color-brand-800); }
.hover\:text-white:hover { color: #fff; }
.hover\:text-slate-400:hover { color: var(--color-slate-400); }
.hover\:border-brand-400:hover { border-color: var(--color-brand-400); }
.hover\:border-transparent:hover { border-color: transparent; }

/* --- Focus --- */
.focus\:border-brand-500:focus { border-color: var(--color-brand-500); }
.focus\:ring-2:focus { box-shadow: 0 0 0 2px var(--color-brand-200); }

/* --- Placeholder --- */
.placeholder\:text-slate-400::placeholder { color: var(--color-slate-400); }

/* --- Disabled --- */
.disabled\:cursor-not-allowed:disabled { cursor: not-allowed; }
.disabled\:opacity-50:disabled { opacity: 0.5; }

/* --- Responsive: sm (640px) --- */
@media (min-width: 640px) {
  .sm\:grid-cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .sm\:p-5 { padding: 1.25rem; }
}

/* --- Responsive: md (768px) --- */
@media (min-width: 768px) {
  .md\:grid-cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .md\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

/* --- Responsive: lg (1024px) --- */
@media (min-width: 1024px) {
  .lg\:hidden { display: none; }
  .lg\:block { display: block; }
  .lg\:flex { display: flex; }
  .lg\:grid-cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .lg\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .lg\:grid-cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .lg\:col-span-2 { grid-column: span 2 / span 2; }
  .lg\:p-8 { padding: 2rem; }
  .lg\:p-12 { padding: 3rem; }
  .lg\:text-3xl { font-size: 1.875rem; line-height: 2.25rem; }
  .lg\:text-4xl { font-size: 2.25rem; line-height: 2.5rem; }
}

/* --- Responsive: xl (1280px) --- */
@media (min-width: 1280px) {
  .xl\:grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .xl\:grid-cols-\[minmax\(0\,2fr\)_minmax\(300px\,1fr\)\] {
    grid-template-columns: minmax(0, 2fr) minmax(300px, 1fr);
  }
}

/* Layout grid đặc thù trang danh mục / tin tức */
@media (min-width: 1024px) {
  .lg\:grid-cols-\[minmax\(0\,2fr\)_340px\] {
    grid-template-columns: minmax(0, 2fr) 340px;
  }
}

